/**
 * @interface
 * response for syntax error of Hygraph API.
 * Syntax error happened when the query
 * does not follow the correct "grammar"
 * of GraphQL.
 *
 * @property
 * `errors` - array of string (string[]) that returns
 * a wrapper for the message
 *
 * `message` - actual message of syntax errors. return
 * as `string`
 *
 * `data` - return as `null`
 *
 * `requestId` - combination of alphabet (a-z)
 * and numbers (0-9), generated by Hygraph API.
 * return as `string`
 *
 * @example
 * Here is the example from Hygraph article
 * {
   "errors": [
     {
       "message": "[line: 1] field 'description' is not defined in 'Project'"
     }
   ],
   "data": null,
   "extensions": {
     "requestId": "clgjsamqwcyns0bmk72uuth88"
   }
 }
 *
 * @see
 * article from Hygraph here:
 * {@link https://hygraph.com/learn/graphql/errors}
 *
 */
export interface HygraphAPISyntaxErrorResponse {
  errors: [
    {
      message: string;
    },
  ];
  data: null;
  extensions: {
    requestId: string;
  };
}

/**
 * @interface
 * structure of validation errors sent by
 * Hygraph API
 *
 * @property
 * `errors` - array of string (`string[]`).
 * wraps the rest property
 *
 * `message` - description of the validation error.
 * return as `string`
 *
 * `locations` - specify where the wrong schema are
 * located, by line and column
 *
 * `line` - exact line where the wrong schema
 * is located. counted from top to bottom.
 * return as `number`
 *
 * `column` - exact column where the wrong schema
 * is located. using LTR (left-to-right) writing
 * direction. return as `number`
 *
 * `code` - Hygraph's customized name for error,
 * all capitalized/uppercase. return as `string`
 *
 * `fieldName` - GraphQL operation name
 * (create, edit, update, etc)
 *
 * `argumentName` - name of parameter
 * that fails to be processed
 *
 *
 * @example
 * {
   "errors": [
     {
       "message": "Variable \"$name\" of required type \"String!\" was not provided.",
       "locations": [
         {
           "line": 3,
           "column": 15
         }
       ],
       "extensions": {
         "code": "GRAPHQL_VALIDATION_FAILED",
         "fieldName": "createUser",
         "argumentName": "name"
       }
     }
   ]
 }
 *
 *
 * @see
 * this article from Hygraph
 * {@link https://hygraph.com/learn/graphql/errors}
 */
export interface HygraphAPIValidationErrorResponse {
  errors: [
    {
      message: string;
      locations: [
        {
          line: number;
          column: number;
        },
      ];
      extensions: {
        code: string;
        fieldName: string;
        argumentName: string;
      };
    },
  ];
}
